package cn.balltv.portal;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.util.*;
public class SeriesSourceTest {
 @Test public void skipsGamblingAndOfflineRooms()throws Exception{assertFalse(SeriesSource.allowed(new JSONObject("{sport_id:10001,status:2,room_title:'百家乐'}")));assertFalse(SeriesSource.allowed(new JSONObject("{sport_id:1,status:1,room_title:'足球'}")));assertTrue(SeriesSource.allowed(new JSONObject("{sport_id:1,status:2,room_title:'甲队VS乙队',user_nickname:'解说'}")));}
 @Test public void incorrectAttachedMatchNeverMergesWithRoomTitle()throws Exception{JSONObject info=new JSONObject("{home_name:'岛根魔术',away_name:'富山松鸡'}");assertFalse(SeriesSource.titleMatches("NBA回放 快船vs鹈鹕",info));assertTrue(SeriesSource.titleMatches("日篮 岛根魔术 vs 富山松鸡",info));}
 @Test public void requestsOnlyAnonymousUnboundQualities()throws Exception{assertFalse(SeriesSource.free(new JSONObject("{switch:1,login_status:1,account_bind:0}")));assertFalse(SeriesSource.free(new JSONObject("{switch:1,login_status:0,account_bind:1}")));assertFalse(SeriesSource.free(new JSONObject("{switch:1}")));assertTrue(SeriesSource.free(new JSONObject("{switch:1,login_status:0,account_bind:0}")));}
 @Test public void publicWebsiteFormSignatureUsesSortedFields()throws Exception{Map<String,String> form=new HashMap<String,String>();form.put("room_id","678572758");form.put("time","1794216592");form.put("code_id","gqzm");assertEquals("cfc19fe6d20ee5fb2ead507839fa64d8",SeriesSource.signature(form));}
 @org.junit.Test public void sharedBackendRoomsKeepAliasesButRemainOneVideoRoom()throws Exception{java.util.LinkedHashMap<String,SeriesSource.Room> rooms=new java.util.LinkedHashMap<String,SeriesSource.Room>();String[] a={"bszb","比赛","https://example.org","https://api.example.org","https://play.example.org"},b={"wqzb","玩球","https://other.org","https://api.other.org","https://play.example.org"};SeriesSource.mergeRoom(rooms,new SeriesSource.Room(a,new org.json.JSONObject("{chatroom_id:123}")));SeriesSource.mergeRoom(rooms,new SeriesSource.Room(b,new org.json.JSONObject("{chatroom_id:123}")));org.junit.Assert.assertEquals(1,rooms.size());org.junit.Assert.assertEquals("比赛/玩球",SeriesSource.roomLabel(rooms.values().iterator().next()));b=b.clone();b[4]="https://different.example.org";SeriesSource.mergeRoom(rooms,new SeriesSource.Room(b,new org.json.JSONObject("{chatroom_id:123}")));org.junit.Assert.assertEquals(2,rooms.size());}
}
